#!/usr/bin/env python3
"""Regenerate include/workspace/exports.h from EXPORTC lines in qlogo/exports/exports*.cpp."""

import subprocess
from pathlib import Path

HEADER = """#ifndef WORKSPACE_EXPORTS_H
#define WORKSPACE_EXPORTS_H

// DO NOT EDIT THIS FILE!
// Any changes to this file will not last long!
// It was generated by update_exports_header.py.
// See util/update_exports_header.py for details.

#include "compiler_types.h"
#include "workspace/exports_internal.h"

"""

FOOTER = """#endif // WORKSPACE_EXPORTS_H
"""

def _repo_root() -> Path:
    result = subprocess.run(
        ["git", "rev-parse", "--show-toplevel"],
        capture_output=True,
        text=True,
        check=True,
        cwd=Path(__file__).resolve().parent,
    )
    return Path(result.stdout.strip())

REPO_ROOT = _repo_root()
HEADER_PATH = REPO_ROOT / "include" / "workspace" / "exports.h"
SOURCE_GLOB = "qlogo/exports/exports*.cpp"


def extract_export_declarations(source_lines: list[str]) -> list[str]:
    """Collect EXPORTC lines from source, normalize to declarations (semicolon, no brace/comments)."""
    declarations = []
    for line in source_lines:
        stripped = line.lstrip()
        if not stripped.startswith("EXPORTC"):
            continue
        sig = stripped.rstrip("\n\r")
        if "//" in sig:
            sig = sig.split("//", 1)[0].rstrip()
        if sig.endswith("{"):
            sig = sig[:-1].rstrip()
        if not sig.endswith(";"):
            sig += ";"
        declarations.append(sig + "\n")
    return declarations


def main() -> None:
    source_paths = sorted(REPO_ROOT.glob(SOURCE_GLOB))
    if not source_paths:
        raise SystemExit(f"No export sources matched {SOURCE_GLOB}")

    declarations = []
    for source_path in source_paths:
        declarations.append("\n")
        declarations.append("//  -------------------------------------------------------------------\n")
        declarations.append(f"//  {source_path.name}\n")
        declarations.append("//  -------------------------------------------------------------------\n")
        declarations.append("\n")
        source_lines = source_path.read_text(encoding="utf-8").splitlines(keepends=True)
        declarations.extend(extract_export_declarations(source_lines))

    HEADER_PATH.write_text(HEADER + "".join(declarations) + FOOTER, encoding="utf-8")


if __name__ == "__main__":
    main()
